sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;


    // =====================================================
    // FILTERS
    // =====================================================

    c.filters = {

        search: "",

        status: "",

        opportunity: ""

    };


    // =====================================================
    // FILTERED APPLICATIONS
    // =====================================================

    c.filteredApplications = [];


    // =====================================================
    // OPPORTUNITY FILTER OPTIONS
    // =====================================================

    c.opportunities = [];


    // =====================================================
    // BUILD OPPORTUNITY LIST
    // =====================================================

    c.buildOpportunityList = function() {

        var applications =
            c.data.applications || [];


        var opportunityMap = {};


        applications.forEach(function(application) {

            var opportunityId =
                application.opportunity_id || "";

            var opportunityTitle =
                application.opportunity_title ||
                "Placement Opportunity";


            if (
                opportunityId &&
                !opportunityMap[opportunityId]
            ) {

                opportunityMap[opportunityId] = true;


                c.opportunities.push({

                    id: opportunityId,

                    title: opportunityTitle

                });

            }

        });


        // Sort opportunities alphabetically

        c.opportunities.sort(function(a, b) {

            return a.title.localeCompare(
                b.title
            );

        });

    };


    // =====================================================
    // APPLY FILTERS
    // =====================================================

    c.applyFilters = function() {

        var applications =
            c.data.applications || [];


        var search =
            (c.filters.search || "")
            .toLowerCase()
            .trim();


        var status =
            c.filters.status || "";


        var opportunity =
            c.filters.opportunity || "";


        c.filteredApplications =
            applications.filter(
                function(application) {


                    // =================================
                    // SEARCH
                    // =================================

                    var student =
                        (
                            application.student_name ||
                            ""
                        )
                        .toLowerCase();


                    var applicationId =
                        (
                            application.application_id ||
                            ""
                        )
                        .toLowerCase();


                    var opportunityTitle =
                        (
                            application.opportunity_title ||
                            ""
                        )
                        .toLowerCase();


                    var location =
                        (
                            application.location ||
                            ""
                        )
                        .toLowerCase();


                    var opportunityId =
                        (
                            application.opportunity_id ||
                            ""
                        )
                        .toLowerCase();


                    var matchesSearch =
                        !search ||

                        student.indexOf(search) !== -1 ||

                        applicationId.indexOf(search) !== -1 ||

                        opportunityTitle.indexOf(search) !== -1 ||

                        opportunityId.indexOf(search) !== -1 ||

                        location.indexOf(search) !== -1;


                    // =================================
                    // STATUS
                    // =================================

                    var matchesStatus =
                        !status ||

                        application.status === status;


                    // =================================
                    // OPPORTUNITY
                    // =================================

                    var matchesOpportunity =
                        !opportunity ||

                        application.opportunity_id ===
                        opportunity;


                    // =================================
                    // FINAL RESULT
                    // =================================

                    return (

                        matchesSearch &&

                        matchesStatus &&

                        matchesOpportunity

                    );

                }
            );

    };


    // =====================================================
    // CLEAR FILTERS
    // =====================================================

    c.clearFilters = function() {

        c.filters.search = "";

        c.filters.status = "";

        c.filters.opportunity = "";

        c.applyFilters();

    };


    // =====================================================
    // INITIALIZE
    // =====================================================

    $scope.$watch(

        function() {

            return c.data.applications;

        },

        function(newValue) {

            if (newValue) {

                // Prevent duplicate opportunity options

                c.opportunities = [];

                c.buildOpportunityList();

                c.applyFilters();

            }

        },

        true

    );


    // =====================================================
    // DASHBOARD
    // =====================================================

    c.goDashboard = function() {

        window.location.href =
            "?id=campus360_recruiter_dashboard_new";

    };

	c.viewStudent = function(studentSysId) {

		if (!studentSysId) {

			return;

		}

		window.location.href =
			'?id=campus360_recruiter_student_view&sys_id=' +
			encodeURIComponent(studentSysId);

	};

};

sp_widget.css:
.applications-page {

  max-width: 1200px;

  margin: 30px auto;

  padding:
    0 20px 50px;

  color: #102a56;

}


/* =========================================
   HEADER
========================================= */

.page-header {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 18px;

  padding: 30px 34px;

  margin-bottom: 24px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  box-shadow:
    0 8px 25px
    rgba(30,55,90,0.08);

}


.eyebrow {

  font-size: 12px;

  font-weight: 700;

  letter-spacing: 2px;

  color: #4d63e8;

}


.page-header h1 {

  margin:
    8px 0 6px;

  font-size: 30px;

  font-weight: 700;

}


.page-header p {

  margin: 0;

  color: #70809d;

  font-size: 14px;

}


.company-info {

  display: inline-block;

  margin-top: 12px;

  padding:
    7px 12px;

  background: #f2f4ff;

  border-radius: 7px;

  color: #5368e8;

  font-size: 12px;

  font-weight: 600;

}


.header-actions {

  display: flex;

  gap: 10px;

}


/* =========================================
   BUTTON
========================================= */

.btn {

  display: inline-flex;

  align-items: center;

  justify-content: center;

  text-decoration: none;

  height: 42px;

  padding:
    0 18px;

  border-radius: 8px;

  font-size: 13px;

  font-weight: 600;

  cursor: pointer;

  box-sizing: border-box;

}


.btn-secondary {

  background: #ffffff;

  color: #5368e8;

  border:
    1px solid #ccd5e5;

}


.btn-secondary:hover {

  background: #f5f7ff;

}


/* =========================================
   STATISTICS
========================================= */

.stats-grid {

  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 18px;

  margin-bottom: 24px;

}


.stat-card {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 15px;

  padding: 20px;

  display: flex;

  align-items: center;

  gap: 15px;

  box-shadow:
    0 5px 18px
    rgba(30,55,90,0.05);

}


.stat-icon {

  width: 45px;

  height: 45px;

  border-radius: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #f1f3ff;

  color: #5368e8;

  font-size: 20px;

}


.stat-icon.pending {

  background: #fff8e9;

  color: #c58a18;

}


.stat-icon.submitted {

  background: #eff6ff;

  color: #3473c5;

}


.stat-icon.selected {

  background: #effaf3;

  color: #25804a;

}


.stat-label {

  color: #7a89a2;

  font-size: 12px;

  margin-bottom: 5px;

}


.stat-value {

  font-size: 24px;

  font-weight: 700;

  color: #20385f;

}


/* =========================================
   LIST CARD
========================================= */

.list-card {

  background: #ffffff;

  border:
    1px solid #e1e7f2;

  border-radius: 18px;

  overflow: hidden;

  box-shadow:
    0 8px 25px
    rgba(30,55,90,0.06);

}


.list-header {

  padding:
    24px 28px;

  display: flex;

  justify-content: space-between;

  align-items: center;

  border-bottom:
    1px solid #e8edf5;

}


.list-header h2 {

  margin:
    0 0 5px;

  font-size: 20px;

}


.list-header p {

  margin: 0;

  color: #7888a3;

  font-size: 13px;

}


.record-count {

  padding:
    7px 12px;

  background: #f2f4ff;

  color: #5368e8;

  border-radius: 7px;

  font-size: 12px;

  font-weight: 600;

}


/* =========================================
   TABLE
========================================= */

.table-wrapper {

  width: 100%;

  overflow-x: auto;

}


.application-table {

  width: 100%;

  border-collapse: collapse;

}


.application-table th {

  padding:
    14px 18px;

  text-align: left;

  background: #f8faff;

  border-bottom:
    1px solid #e4eaf3;

  color: #71809a;

  font-size: 11px;

  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: .4px;

  white-space: nowrap;

}


.application-table td {

  padding:
    17px 18px;

  border-bottom:
    1px solid #edf1f6;

  font-size: 13px;

  color: #405575;

  white-space: nowrap;

}


.application-table tbody tr:hover {

  background: #fafbff;

}


/* =========================================
   STUDENT
========================================= */

.student-cell {

  display: flex;

  align-items: center;

  gap: 10px;

}


.student-avatar {

  width: 34px;

  height: 34px;

  border-radius: 50%;

  background: #f1f3ff;

  color: #5368e8;

  display: flex;

  align-items: center;

  justify-content: center;

  font-weight: 700;

  font-size: 12px;

}


.student-cell strong {

  color: #20385f;

  font-size: 13px;

}


/* =========================================
   APPLICATION ID
========================================= */

.application-id {

  color: #5368e8;

  font-size: 12px;

  font-weight: 600;

}


/* =========================================
   OPPORTUNITY
========================================= */

.opportunity-cell {

  display: flex;

  flex-direction: column;

  gap: 4px;

}


.opportunity-cell strong {

  color: #20385f;

  font-size: 13px;

}


.opportunity-cell span {

  color: #8a97aa;

  font-size: 11px;

}


/* =========================================
   STATUS
========================================= */

.status-badge {

  display: inline-block;

  padding:
    5px 10px;

  border-radius: 20px;

  font-size: 11px;

  font-weight: 700;

}


.status-pending {

  background: #fff5dc;

  color: #a9740b;

}


.status-submitted {

  background: #eaf2ff;

  color: #346eb9;

}


.status-selected {

  background: #eaf8ef;

  color: #25804a;

}


.status-other {

  background: #f1f3f6;

  color: #68758a;

}


/* =========================================
   EMPTY STATE
========================================= */

.empty-state {

  text-align: center;

  padding:
    70px 30px;

}


.empty-icon {

  width: 55px;

  height: 55px;

  margin:
    0 auto 15px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #f2f4ff;

  border-radius: 14px;

  color: #5368e8;

  font-size: 24px;

}


.empty-state h3 {

  margin:
    0 0 8px;

  font-size: 18px;

  color: #20385f;

}


.empty-state p {

  max-width: 450px;

  margin:
    0 auto;

  color: #7c8ba2;

  font-size: 13px;

  line-height: 1.6;

}


/* =========================================
   ERROR
========================================= */

.error-message {

  margin-bottom: 20px;

  padding:
    13px 16px;

  border-radius: 8px;

  background: #fff1f1;

  border:
    1px solid #ffd1d1;

  color: #c63f3f;

  font-size: 13px;

}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 900px) {

  .stats-grid {

    grid-template-columns:
      repeat(2, 1fr);

  }

}


@media (max-width: 600px) {

  .page-header {

    flex-direction: column;

    align-items: flex-start;

  }


  .stats-grid {

    grid-template-columns: 1fr;

  }


  .list-header {

    flex-direction: column;

    align-items: flex-start;

    gap: 12px;

  }

}

/* ==========================================
   APPLICATION FILTERS
========================================== */

.application-filters {

    margin-top: 22px;

    display: flex;

    align-items: center;

    gap: 12px;

    padding: 15px;

    background: #f8faff;

    border: 1px solid #e2e8f5;

    border-radius: 12px;
}


/* SEARCH */

.search-box {

    flex: 1;

    height: 44px;

    position: relative;

}


.search-box input {

    width: 100%;

    height: 44px;

    box-sizing: border-box;

    border: 1px solid #d5deee;

    border-radius: 8px;

    background: #ffffff;

    padding: 0 15px 0 38px;

    font-size: 13px;

    color: #24395f;

    outline: none;

}


.search-box input:focus {

    border-color: #5368e8;

    box-shadow:
        0 0 0 3px rgba(83,104,232,0.10);

}


.search-icon {

    position: absolute;

    left: 13px;

    top: 12px;

    color: #70809d;

    font-size: 17px;

    z-index: 2;

}


/* STATUS FILTER */

.filter-box {

    width: 180px;

}


.filter-box select {

    width: 100%;

    height: 44px;

    border: 1px solid #d5deee;

    border-radius: 8px;

    background: #ffffff;

    padding: 0 12px;

    font-size: 13px;

    color: #24395f;

    outline: none;

}


.filter-box select:focus {

    border-color: #5368e8;

}


/* CLEAR BUTTON */

.clear-filter-btn {

    height: 44px;

    padding: 0 18px;

    border-radius: 8px;

    border: 1px solid #d2daea;

    background: #ffffff;

    color: #5368e8;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;

}


.clear-filter-btn:hover {

    background: #f1f4ff;

}


/* RESULT COUNT */

.filter-result {

    margin: 12px 2px 0;

    font-size: 12px;

    color: #7b8aa4;

}


.filter-result strong {

    color: #30466d;

}


/* ==========================================
   NO RESULTS
========================================== */

.no-results {

    text-align: center;

    padding: 50px 20px !important;

    color: #6f7f99;

}


.no-results-icon {

    font-size: 28px;

    margin-bottom: 10px;

}


.no-results strong {

    display: block;

    color: #30466d;

    font-size: 14px;

}


.no-results p {

    margin-top: 6px;

    font-size: 12px;

}


/* ==========================================
   MOBILE
========================================== */

@media (max-width: 768px) {

    .application-filters {

        flex-direction: column;

        align-items: stretch;

    }


    .search-box {

        width: 100%;

    }


    .filter-box {

        width: 100%;

    }


    .clear-filter-btn {

        width: 100%;

    }

}


.view-student-btn {
    border: 1px solid #4f63e8;
    background: #ffffff;
    color: #4f63e8;
    padding: 7px 14px;
    border-radius: 7px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.view-student-btn:hover {
    background: #4f63e8;
    color: #ffffff;
}

sp_widget.script:
(function() {

    // =====================================================
    // CAMPUS360 RECRUITER APPLICATIONS
    // =====================================================

    // Current recruiter
    data.recruiter_name = 'Ananya Mehta';
    data.recruiter_id = 'RCR001';


    // =====================================================
    // CURRENT COMPANY
    // =====================================================

    var companySysId =
        'e9268662acd303107f44b432e349694b';


    // =====================================================
    // GET COMPANY
    // =====================================================

    var companyGR =
        new GlideRecord(
            'x_snc_campus360_company_master'
        );


    if (!companyGR.get(companySysId)) {

        data.error =
            'Company record could not be found.';

        return;

    }


    data.company_name =
        companyGR.getValue('company_name');

    data.company_id =
        companyGR.getValue('company_id');


    // =====================================================
    // INITIAL VALUES
    // =====================================================

    data.total_count = 0;
    data.pending_count = 0;
    data.submitted_count = 0;
    data.selected_count = 0;


    data.applications = [];


    // =====================================================
    // APPLICATIONS
    // =====================================================

    var applicationGR =
        new GlideRecord(
            'x_snc_campus360_student_application'
        );


    /*
     * IMPORTANT
     *
     * Application
     *      ↓
     * Opportunity
     *      ↓
     * Company
     *
     * Only retrieve applications belonging
     * to the current company.
     */

    applicationGR.addQuery(
        'opportunity.company',
        companySysId
    );


    applicationGR.orderByDesc(
        'sys_created_on'
    );


    applicationGR.query();


    while (applicationGR.next()) {


        var application = {};


        // =================================================
        // BASIC INFORMATION
        // =================================================

        application.sys_id =
            applicationGR.getUniqueValue();


        application.application_id =
            applicationGR.getValue(
                'application_id'
            );


        // =================================================
        // STUDENT
        // =================================================

        if (applicationGR.student) {

			application.student_name =
				applicationGR.student.getDisplayValue();

			// Student Master sys_id
			application.student_sys_id =
				applicationGR.getValue('student');

		} else {

			application.student_name =
				'Student';

			application.student_sys_id =
				'';

		}


        // =================================================
        // OPPORTUNITY
        // =================================================

        if (applicationGR.opportunity) {

            var opportunityGR =
                applicationGR.opportunity.getRefRecord();


            if (
                opportunityGR &&
                opportunityGR.isValidRecord()
            ) {

                application.opportunity_title =
                    opportunityGR.getValue(
                        'opportunity_title'
                    );


                application.opportunity_id =
                    opportunityGR.getValue(
                        'opportunity_id'
                    );


                application.location =
                    opportunityGR.getValue(
                        'location'
                    );


                application.ctc =
                    opportunityGR.getValue(
                        'ctc_stipend'
                    );

            } else {

                application.opportunity_title =
                    'Placement Opportunity';

                application.opportunity_id =
                    '';

                application.location =
                    '';

                application.ctc =
                    '';

            }

        } else {

            application.opportunity_title =
                'Placement Opportunity';

            application.opportunity_id =
                '';

            application.location =
                '';

            application.ctc =
                '';

        }


        // =================================================
        // APPLICATION STATUS
        // =================================================

        application.status =
            applicationGR.getDisplayValue(
                'application_status'
            );


        // =================================================
        // APPLIED DATE
        // =================================================

        application.applied_date =
            applicationGR.getDisplayValue(
                'applied_date'
            );


        // =================================================
        // UPDATE COUNTS
        // =================================================

        data.total_count++;


        var status =
            applicationGR.getValue(
                'application_status'
            );


        if (status == 'Pending') {

            data.pending_count++;

        }


        if (status == 'Submitted') {

            data.submitted_count++;

        }


        if (status == 'Selected') {

            data.selected_count++;

        }


        // =================================================
        // ADD APPLICATION
        // =================================================

        data.applications.push(
            application
        );

    }


})();
